-- =====================================================================
-- Migration 077: RU proxy role and selective egress policy
-- =====================================================================

SET @col_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'vpn_servers' AND COLUMN_NAME = 'role'
);
SET @sql := IF(@col_exists = 0,
  "ALTER TABLE vpn_servers ADD COLUMN role ENUM('vpn','ru_proxy') NOT NULL DEFAULT 'vpn' AFTER user_id, ADD INDEX idx_role (role)",
  "SELECT 1"
);
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

CREATE TABLE IF NOT EXISTS ru_proxy_configs (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  server_id INT UNSIGNED NOT NULL UNIQUE,
  transport ENUM('wireguard','awg2') NOT NULL DEFAULT 'wireguard',
  listen_port INT UNSIGNED NULL,
  tunnel_subnet VARCHAR(50) NOT NULL DEFAULT '10.250.0.0/16',
  public_key TEXT NULL,
  endpoint VARCHAR(255) NULL,
  status ENUM('active','inactive','error') NOT NULL DEFAULT 'inactive',
  last_applied_at TIMESTAMP NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_transport (transport),
  INDEX idx_status (status),
  FOREIGN KEY (server_id) REFERENCES vpn_servers(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS egress_route_policies (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  server_id INT UNSIGNED NOT NULL,
  proxy_server_id INT UNSIGNED NULL,
  transport ENUM('wireguard','awg2') NOT NULL DEFAULT 'wireguard',
  enabled TINYINT(1) NOT NULL DEFAULT 0,
  fallback_mode ENUM('warp','direct','block') NOT NULL DEFAULT 'warp',
  last_applied_at TIMESTAMP NULL,
  last_error TEXT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uniq_server_policy (server_id),
  INDEX idx_proxy_server (proxy_server_id),
  FOREIGN KEY (server_id) REFERENCES vpn_servers(id) ON DELETE CASCADE,
  FOREIGN KEY (proxy_server_id) REFERENCES vpn_servers(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS egress_route_rules (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  policy_id INT UNSIGNED NOT NULL,
  type ENUM('ip','cidr','domain') NOT NULL,
  value VARCHAR(255) NOT NULL,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  comment VARCHAR(255) NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uniq_policy_value (policy_id, type, value),
  INDEX idx_policy_enabled (policy_id, enabled),
  FOREIGN KEY (policy_id) REFERENCES egress_route_policies(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS egress_route_resolved_ips (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  rule_id INT UNSIGNED NOT NULL,
  ip VARCHAR(45) NOT NULL,
  last_resolved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uniq_rule_ip (rule_id, ip),
  FOREIGN KEY (rule_id) REFERENCES egress_route_rules(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

